// Parks the generated bytes of an archive in one stream-built Blob. Browsers
// keep such a Blob out of script memory (Chromium writes it to disk), unlike a
// Blob assembled from many in-memory buffers. Bytes are written in the order
// they are produced; the archive is later composed from slices of the Blob.

export type FolderZipSinkRange = { start: number; end: number };

export type FolderZipSink = {
  /** Appends bytes and returns where they will be in the finished Blob. */
  write(bytes: Uint8Array<ArrayBuffer>): FolderZipSinkRange;
  close(): Promise<Blob>;
  abort(reason?: unknown): void;
};

// Small writes, such as the header of a referenced entry, share one chunk.
const STAGE_BYTES = 64 * 1024;
const STAGED_WRITE_BYTES = 8 * 1024;

export function createFolderZipSink({
  onQueued,
  onWritten,
  onError,
}: {
  /** Bytes were handed to the stream and are held until `onWritten`. */
  onQueued(bytes: number): void;
  onWritten(bytes: number): void;
  onError(error: unknown): void;
}): FolderZipSink {
  const { readable, writable } = new TransformStream<
    Uint8Array<ArrayBuffer>,
    Uint8Array<ArrayBuffer>
  >();
  const blob = new Response(readable).blob();
  blob.catch(() => undefined);
  const writer = writable.getWriter();
  writer.closed.catch(() => undefined);
  let position = 0;
  let stage = new Uint8Array(STAGE_BYTES);
  let staged = 0;

  const enqueue = (chunk: Uint8Array<ArrayBuffer>) => {
    onQueued(chunk.length);
    writer.write(chunk).then(() => onWritten(chunk.length), onError);
  };
  const flushStage = () => {
    if (staged === 0) return;
    enqueue(stage.subarray(0, staged));
    stage = new Uint8Array(STAGE_BYTES);
    staged = 0;
  };

  return {
    write(bytes) {
      const start = position;
      position += bytes.length;
      if (bytes.length > STAGED_WRITE_BYTES) {
        flushStage();
        enqueue(bytes);
      } else if (bytes.length > 0) {
        if (staged + bytes.length > STAGE_BYTES) flushStage();
        stage.set(bytes, staged);
        staged += bytes.length;
      }
      return { start, end: position };
    },
    async close() {
      flushStage();
      await writer.close();
      return blob;
    },
    abort(reason) {
      writer.abort(reason).catch(() => undefined);
    },
  };
}
